window.docContents[109].resolve({"/rules/RG1002/#RG1002-limitations":{"contents":"In the editor the rule is reported for completed declarations of the current snapshot. A cancelled collection reports nothing for that declaration; a failed one is reported as RG2005 (incomplete), never as an invented RG1002.\n\nThe checked example below comes from a diagnostic single-file inspection that keeps Lean's sorry warning as related evidence and continues to policy inspection; the ordinary project commands stop earlier with RG2003, as described above.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG1002: Proof holes are forbidden","header":"Limitations and unsupported cases","id":"/rules/RG1002/#RG1002-limitations"},"/rules/RG2001/#RG2001-limitations":{"contents":"This page's example is a diagnostic demonstration: the violating run is INCOMPLETE by design and is not accepted negative evidence. Its corrected counterpart passed a completed positive check.\n\n","context":"Regula rule reference\u0009Rule index\u0009RG2001: The declared Lean environment must be available","header":"Limitations and unsupported cases","id":"/rules/RG2001/#RG2001-limitations"}});